import test from "node:test";
import assert from "node:assert/strict";
import {canonicalTWAP} from "../twap.mjs";
import {PUMP_ECONOMICS,graduationAccounting,MemoryPumpLifecycleStore,recordTokenCreation,recordGraduation,reserveCreatorReward,reconcileCreatorReward,recordMarketTransition} from "../pump.mjs";
const now=Date.parse("2026-10-12T12:00:00Z");
const token={verified:true,tokenId:"fixture-token",creator:"creator-a",chainId:"fixture-chain",decimals:6,codeHash:"fixture-code",mintingLocked:true,totalSupplyBaseUnits:"1000000000000000"};
const proof=(kind,patch={})=>({verified:true,kind,tokenId:token.tokenId,chainId:token.chainId,reference:"fixture:"+kind,height:"1",blockHash:"fixture-block",priceMaxAgeSeconds:60,...patch});
const pricePolicy={approved:true,version:"FIXTURE-TWAP",poolId:"fixture-price-pool",baseAssetId:"RIO",quoteAssetId:"RUSD",chainId:token.chainId,windowSeconds:600,maxGapSeconds:600,maxAgeSeconds:600,minimumObservations:2};
const observations=[600000,1000].map((age,i)=>({verified:true,timestamp:new Date(now-age).toISOString(),poolId:pricePolicy.poolId,baseAssetId:"RIO",quoteAssetId:"RUSD",chainId:token.chainId,reference:"fixture:price:"+i,height:String(i+1),blockHash:"fixture-price-"+i,priceNumerator:"1",priceDenominator:"10"}));
const input={token,now,price:canonicalTWAP(pricePolicy,observations,now),proof:proof("market_state"),realRioReserveUrio:"500000000000",circulatingTokenBaseUnits:"800000000000000",tokenSpotPriceRioScaled:"812500000000000"};
async function graduated(){const store=new MemoryPumpLifecycleStore();await recordTokenCreation(store,token,proof("creation"));const a=graduationAccounting(input);await recordGraduation(store,token.tokenId,token.creator,input,proof("rio_liquidity_seed",{nativeAmountUrio:a.requiredSeedUrio,lpLocked:true,poolId:"fixture-rio-pool"}));return store;}
test("65K market cap and 15K seed remain distinct from actual post-seed surplus",()=>{const a=graduationAccounting(input);assert.equal(a.marketCapLeri,"65000000000");assert.equal(a.requiredSeedUrio,"150000000000");assert.equal(a.postSeedSurplusUrio,"350000000000");assert.equal(a.creatorRewardReserveUrio,"35000000000");assert.notEqual(a.creatorRewardReserveUrio,"50000000000");assert.equal(PUMP_ECONOMICS.stages.reduce((n,s)=>n+s.bps,0),1000);});
test("missing, stale, zero, manipulated and unapproved prices cannot prepare a seed",()=>{for(const price of [null,{...input.price,available:false},{...input.price,priceScaled:"0"},{...input.price,windowEnd:new Date(now-61000).toISOString()},{...input.price,provenance:[]},{...input.price,authoritative:false}])assert.throws(()=>graduationAccounting({...input,price}));assert.throws(()=>graduationAccounting({...input,realRioReserveUrio:"149999999999"}),/NOT_FUNDED/);assert.throws(()=>graduationAccounting({...input,tokenSpotPriceRioScaled:"812499999999999"}),/THRESHOLD/);});
test("creator and token substitution cannot graduate or redirect reward claims",async()=>{const store=await graduated();await assert.rejects(()=>recordGraduation(store,token.tokenId,"creator-b",input,proof("rio_liquidity_seed")),/AUTHORIZATION/);await assert.rejects(()=>reserveCreatorReward(store,"other-token",token.creator,"stage_one",{},"key"),/AUTHORIZATION/);});
const eligibility=proof("reward_eligibility",{genuineBuyerAuthority:true,genuineBuyers:1000,marketCapLeri:"1000000000000",sustainedSeconds:345600,lpSeedVerified:true,antiAbuseCleared:true,verifiedSwaps:1000});
test("genuine-buyer minimum and target bands are not exclusive windows or duplicate claims",async()=>{for(const [stage,min] of [["stage_one",200],["stage_two",250],["stage_three",600]]){const store=await graduated();await assert.rejects(()=>reserveCreatorReward(store,token.tokenId,token.creator,stage,{...eligibility,genuineBuyers:min-1},"key"),/ELIGIBILITY/);const claim=await reserveCreatorReward(store,token.tokenId,token.creator,stage,{...eligibility,genuineBuyers:min},"key");assert.equal(claim.status,"RESERVED");await assert.rejects(()=>reserveCreatorReward(store,token.tokenId,token.creator,stage,eligibility,"different-key"),/ALREADY_RESERVED/);}});
test("concurrent stages cannot exceed the creator's 10% reserve and replay is idempotent",async()=>{const store=await graduated();const claims=await Promise.all(PUMP_ECONOMICS.stages.map(s=>reserveCreatorReward(store,token.tokenId,token.creator,s.id,eligibility,s.id)));assert.equal(claims.reduce((n,c)=>n+BigInt(c.quantityUrio),0n),35000000000n);const repeated=await reserveCreatorReward(store,token.tokenId,token.creator,"stage_one",eligibility,"stage_one");assert.equal(repeated.quantityUrio,claims[0].quantityUrio);await assert.rejects(()=>reconcileCreatorReward(store,token.tokenId,"creator-b","stage_one",{}),/STATE_INVALID/);await assert.rejects(()=>reconcileCreatorReward(store,token.tokenId,token.creator,"stage_one",proof("reward_payment",{recipient:"creator-b",quantityUrio:claims[0].quantityUrio,txHash:"fixture",code:0})),/PAYMENT_PROOF/);});
test("fake buyers, insufficient sustain, unsupported reserve and fake migrations fail closed",async()=>{for(const patch of [{genuineBuyerAuthority:false},{antiAbuseCleared:false},{lpSeedVerified:false},{sustainedSeconds:1},{verifiedSwaps:999}]){const store=await graduated();await assert.rejects(()=>reserveCreatorReward(store,token.tokenId,token.creator,"stage_three",{...eligibility,...patch},"key"),/ELIGIBILITY/);}const store=await graduated();await assert.rejects(()=>recordMarketTransition(store,token.tokenId,token.creator,"RIOEX_MARKET_VERIFIED",proof("rioex_migration")),/STATE_INVALID/);await assert.rejects(()=>recordMarketTransition(store,token.tokenId,token.creator,"RUSD_LIQUIDITY_VERIFIED",proof("rusd_liquidity")),/UNPROVEN/);await recordMarketTransition(store,token.tokenId,token.creator,"RUSD_LIQUIDITY_VERIFIED",proof("rusd_liquidity",{canonicalRusdIdentity:true,reserveAuthority:true,lpOwnerVerified:true,settlementVerified:true}));await recordMarketTransition(store,token.tokenId,token.creator,"RIOEX_MARKET_VERIFIED",proof("rioex_migration",{registryVerified:true,settlementVerified:true,supplyReconciled:true,poolOwnershipVerified:true}));assert.equal(store.tokens.get(token.tokenId).stage,"RIOEX_MARKET_VERIFIED");});
